import{_ as l,c as i,o as e,al as r}from"./chunks/framework.B5Yvbuyk.js";const b=JSON.parse('{"title":"宏观经济学 第三版","description":"","frontmatter":{"title":"宏观经济学 第三版","hugoSource":"books/宏观经济学-第三版.md","outline":[1,6]},"headers":[],"relativePath":"Books/2026-11-17-宏观经济学-第三版.md","filePath":"Books/2026-11-17-宏观经济学-第三版.md"}'),h={name:"Books/2026-11-17-宏观经济学-第三版.md"};function n(t,a,o,s,d,c){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="宏观经济学-第三版" tabindex="-1">宏观经济学 第三版 <a class="header-anchor" href="#宏观经济学-第三版" aria-label="Permalink to “宏观经济学 第三版”">​</a></h1><h2 id="第1章-经济学原理的实践" tabindex="-1">第1章 经济学原理的实践 <a class="header-anchor" href="#第1章-经济学原理的实践" aria-label="Permalink to “第1章 经济学原理的实践”">​</a></h2><h2 id="第2章-经济科学-运用数据和模型理解世界" tabindex="-1">第2章 经济科学：运用数据和模型理解世界 <a class="header-anchor" href="#第2章-经济科学-运用数据和模型理解世界" aria-label="Permalink to “第2章 经济科学：运用数据和模型理解世界”">​</a></h2><h2 id="第3章-优化-竭力做到最好" tabindex="-1">第3章 优化：竭力做到最好 <a class="header-anchor" href="#第3章-优化-竭力做到最好" aria-label="Permalink to “第3章 优化：竭力做到最好”">​</a></h2><h2 id="第4章-需求-供给与均衡" tabindex="-1">第4章 需求，供给与均衡 <a class="header-anchor" href="#第4章-需求-供给与均衡" aria-label="Permalink to “第4章 需求，供给与均衡”">​</a></h2><h2 id="第5章-国家财富-定义和测算宏观经济总量" tabindex="-1">第5章 国家财富：定义和测算宏观经济总量 <a class="header-anchor" href="#第5章-国家财富-定义和测算宏观经济总量" aria-label="Permalink to “第5章 国家财富：定义和测算宏观经济总量”">​</a></h2><h2 id="第6章-总收入" tabindex="-1">第6章 总收入 <a class="header-anchor" href="#第6章-总收入" aria-label="Permalink to “第6章 总收入”">​</a></h2><h2 id="第7章-经济增长" tabindex="-1">第7章 经济增长 <a class="header-anchor" href="#第7章-经济增长" aria-label="Permalink to “第7章 经济增长”">​</a></h2><h2 id="第8章-为什么很多地区仍然不发达" tabindex="-1">第8章 为什么很多地区仍然不发达？ <a class="header-anchor" href="#第8章-为什么很多地区仍然不发达" aria-label="Permalink to “第8章 为什么很多地区仍然不发达？”">​</a></h2><h2 id="第9章-就业与失业" tabindex="-1">第9章 就业与失业 <a class="header-anchor" href="#第9章-就业与失业" aria-label="Permalink to “第9章 就业与失业”">​</a></h2><h2 id="第10章-信贷市场" tabindex="-1">第10章 信贷市场 <a class="header-anchor" href="#第10章-信贷市场" aria-label="Permalink to “第10章 信贷市场”">​</a></h2><ul><li><p><strong>信贷</strong>：我们把包括企业家、购房者和学生在内的借款主体称为<strong>债务人</strong>，他们所借入的资金被称为<strong>信贷</strong></p></li><li><p>借款当然不是免费的，借款人需要支付利息。借款的初始金额被称为<strong>本金</strong>。利率是借款者在偿还本金之外，需要（在满一年时）为每1美元贷款支付的额外费用。也可以说，利率就是一笔1美元贷款的<strong>年度成本</strong>。</p></li><li><p>如果你借了1年期利率为i的L美元，1年后你要偿还本金L美元加上i×L美元的利息。为了和实际利率区分开来，我们把利率i称为<strong>名义利率</strong>。</p></li><li><p>实际利率=名义利率-通货膨胀率</p><ul><li>实际GDP=名义GDP-通货膨胀率</li><li>几乎所有的贷款都是以<strong>名义利率</strong>发放的 <ul><li>我现在理解了韩秀云说的贷款买房比全款买房更好，因为实际利率会随着通货膨胀越来越低，甚至可能低于越来的本金</li></ul></li></ul></li><li><p>通货膨胀率指的是整体经济中物价上涨的速度。</p><ul><li>其他条件不变时，通货膨胀率越高，企业销售的商品和服务价格就会越高，在给定的名义利率下偿还贷款就会越容易。</li></ul></li><li><p>信贷需求曲线：信贷需求量与实际利率之间的关系</p><ul><li>政府所感知到的商业机会变化、家庭偏好或预期的变化、政府政策的变化，会使得信贷需求曲线左移或右移</li></ul></li><li><p>实际利率：人们因存钱而得到的回报，因为今天存的1美元，在一年后的购买力是1+r美元，其中r是实际利率</p><ul><li>换句话说，实际利率是当前消费的机会成本，也就是你基于未来的购买力而放弃的东西。因此，较高的实际利率会增加当前消费的机会成本，鼓励更高水平的储蓄。</li><li>真实市场中，为了补偿出借人，具有不同违约风险的借款者需面对不同的实际利率。</li></ul></li><li><p>信贷供给曲线：信贷供给量与实际利率之间的关系</p><ul><li>信贷供给曲线的移动则源于实际利率不变的情况下，追求优化的经济主体储蓄动机的变化（家庭储蓄动机的变化、企业储蓄动机的变化）</li></ul></li><li><p>人们为什么要储蓄？</p><ul><li>为退休储蓄</li><li>为孩子存钱</li><li>为一些可预见的大额支出而存钱</li><li>投资个人事业而存钱</li><li>以备不时之需</li></ul></li><li><p>信贷市场：借款者从储蓄者那里获取资金的市场，有时也被称为可贷资金市场</p><ul><li>信贷市场均衡：信贷供给曲线与信贷需求曲线的交点所对应的实际利率和信贷量 <ul><li>交点决定了市场中的信贷总量(Q*)和均衡实际利率(r*)。在均衡实际利率下，信贷需求量等于信贷供给量。实际利率高于均衡水平将导致超额的信贷供给，这通常会给实际利率带来下行压力。实际利率低于均衡水平将导致超额的信贷需求，给实际利率带来上行压力。</li></ul></li></ul></li><li><p>信贷市场的作用：通过使储蓄者把多余的钱出借给借款者，信贷市场改善了经济中的资源配置</p></li><li><p>金融资本：金融资本存在多种不同的形式，包括信贷（也被称为债务）和股权。</p><ul><li>当一个储蓄者将其存款变成信贷时，他就把自己的储蓄借给了另一个人，换来的是连本带息偿还贷款的承诺。</li><li>当一个储蓄者把自己的存款变成股权时，他就利用其储蓄变成了一家公司的股东，这意味着他获得了公司的所有权和对公司未来利润的索取权。这些利润会以股息的形式支付给公司股东。</li></ul></li><li><p>独角兽：越来越多科技初创公司的市值超过10亿美元。在向公众发行股票之前估值超过这一门槛的公司被称为独角兽。</p></li></ul><h2 id="第11章-货币体系" tabindex="-1">第11章 货币体系 <a class="header-anchor" href="#第11章-货币体系" aria-label="Permalink to “第11章 货币体系”">​</a></h2><h2 id="第12章-短期波动" tabindex="-1">第12章 短期波动 <a class="header-anchor" href="#第12章-短期波动" aria-label="Permalink to “第12章 短期波动”">​</a></h2><h2 id="第13章-逆周期宏观经济政策" tabindex="-1">第13章 逆周期宏观经济政策 <a class="header-anchor" href="#第13章-逆周期宏观经济政策" aria-label="Permalink to “第13章 逆周期宏观经济政策”">​</a></h2><h2 id="第14章-宏观经济学和国际贸易" tabindex="-1">第14章 宏观经济学和国际贸易 <a class="header-anchor" href="#第14章-宏观经济学和国际贸易" aria-label="Permalink to “第14章 宏观经济学和国际贸易”">​</a></h2><h2 id="第15章-开放经济的宏观经济学" tabindex="-1">第15章 开放经济的宏观经济学 <a class="header-anchor" href="#第15章-开放经济的宏观经济学" aria-label="Permalink to “第15章 开放经济的宏观经济学”">​</a></h2>',17)])])}const _=l(h,[["render",n]]);export{b as __pageData,_ as default};
